const http = require('http');
const assert = require('assert');
const { fetchJson } = require('./client');
const server = http.createServer((req, res) => {
  if (req.url === '/redirect') { res.writeHead(302, { Location: '/ok' }); res.end(); return; }
  if (req.url === '/ok') { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ ok: true })); return; }
  res.writeHead(404); res.end('{}');
});
server.listen(0, async () => {
  const port = server.address().port;
  const base = `http://127.0.0.1:${port}`;
  const a = await fetchJson(base + '/ok');
  assert.deepStrictEqual(a, { ok: true });
  const b = await fetchJson(base + '/redirect');
  assert.deepStrictEqual(b, { ok: true });
  console.log('ok');
  server.close();
});
